fn prime_num(n: u64) -> bool {
    // Since the problem states n >= 2, we don't need to handle n < 2 cases.
    // Check divisors from 2 up to sqrt(n).
    // If any divisor divides n exactly, n is not prime.
    let limit = (n as f64).sqrt() as u64;
    for k in 2..=limit {
        if n % k == 0 {
            return false;
        }
    }
    true
}